/**
 * A3 — cross-SDK numeric interop. A Go-signed ecdsa-rdfc-2019 credential whose
 * credentialSubject carries native numeric claims (integer `age`, decimal
 * `score`) must verify in TS. This proves the TS native canonicalizer
 * (documentDigest / proofHashData via canonicalizeRDF) preserves JSON number
 * types byte-identically to Go's processor.Canonicalize — the coercing legacy
 * canonicalizer (numbers -> xsd:string) would produce a different digest and
 * fail here.
 *
 * The fixture was generated by a Go program using a FIXED P-256 private key, so
 * the issuer DID document is rebuilt from that same key below.
 */
import { readFileSync } from 'fs';
import { join } from 'path';
import { p256 } from '@noble/curves/nist';
import { hexToBytes } from '../../src/common/crypto/hex';
import { JSONCredential } from '../../src/vc/json-credential';
import {
  DIDDocument,
  ResolverProvider,
} from '../../src/common/verification-method';

// Must match credential/examples/tsfixturegen (the throwaway Go generator).
const P256_PRIV = '1a2b3c4d5e6f70818243a4b5c6d7e8f9000102030405060708090a0b0c0d0e0f';
const ISSUER = 'did:example:issuer';

class StaticResolver implements ResolverProvider {
  constructor(private readonly doc: DIDDocument) {}
  async resolveDocument(): Promise<DIDDocument> {
    return this.doc;
  }
}

function issuerDID(): DIDDocument {
  const pub = p256.getPublicKey(hexToBytes(P256_PRIV), false); // 0x04 || X || Y
  const x = Buffer.from(pub.slice(1, 33)).toString('base64url');
  const y = Buffer.from(pub.slice(33, 65)).toString('base64url');
  return {
    '@context': [],
    id: ISSUER,
    verificationMethod: [
      {
        id: `${ISSUER}#key-1`,
        type: 'JsonWebKey2020',
        controller: ISSUER,
        publicKeyJwk: { kty: 'EC', crv: 'P-256', x, y },
      },
    ],
    authentication: [`${ISSUER}#key-1`],
    assertionMethod: [`${ISSUER}#key-1`],
  };
}

describe('A3: Go-signed ecdsa-rdfc-2019 numeric interop', () => {
  const fixture = readFileSync(
    join(__dirname, '../fixtures/go-rdfc-numeric/credential.json'),
    'utf8',
  );

  it('carries an integer and a decimal claim', () => {
    const subj = JSON.parse(fixture).credentialSubject;
    expect(subj.age).toBe(42);
    expect(Number.isInteger(subj.age)).toBe(true);
    expect(subj.score).toBe(3.14);
    expect(Number.isInteger(subj.score)).toBe(false);
  });

  it('verifies the Go-signed credential in TS', async () => {
    const cred = await JSONCredential.parse(fixture);
    await cred.verify({ resolver: new StaticResolver(issuerDID()) });
  });
});
